const p = $input.first().json;
if (!p.mode || p.mode !== 'preview_only') {
  throw new Error('Refusing non-preview outreach');
}
return [{
  json: {
    preview: true,
    business: p.business_name,
    channel_hint: p.whatsapp || p.phone || p.email,
    demo_path: p.demo_path,
    message: `Assalam o Alaikum — we built a free VIP demo for ${p.business_name}. Review before any send.`
  }
}];
